import { test, expect } from '@playwright/test';

test.describe('User Login Functionality', () => {
  test('should log out successfully', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/login');
    await page.fill('#user_name', 'standard_user');
    await page.fill('#password', 'secret_sauce');
    await page.click('#react-burger-menu-btn');
    await page.click('#logout_sidebar_link');
    await expect(page).toHaveURL('https://www.saucedemo.com/login');
    await expect(page.locator('#login-button')).toBeVisible();
  });

  test('should not log out when not signed in', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/login');
    await page.click('#react-burger-menu-btn');
    await page.click('#logout_sidebar_link');
    await expect(page).toHaveURL('https://www.saucedemo.com/login');
    await expect(page.locator('#login-button')).toBeVisible();
  });
});
